preConditionHook:
// A NEW EXTREME HAS BEEN MADE AND NO BAR HAS CLOSED BACK THROUGH EVEN A
// SHALLOW RETRACEMENT OF THE LEG. The ABSENCE of any proper pullback, read as
// a sign of strength in its own right (T24-11).
//
// MEASURED BY PRICE, unlike its two relatives: HigherLowStreak measures "no
// pullback" by BARS and MaxPullbackDepthBelowThreshold by the DEPTH of the
// worst give-back against an external threshold. This one is a LATCH -- once
// a close comes back through the retracement level the leg is disqualified
// for good, however shallow the give-back afterwards -- and it fires only on
// the bar that makes the new extreme, so all three fire on different bars.
// All three should be compared before more than one is placed together.
//
// THE LEG IS THE ALWAYS-IN LEG, the standing corpus decision, inlined here as
// TrendDurationBars inlines it and with the same inputs so every consumer
// reads the same state: the direction FLIPS on consecutiveBars consecutive
// STRONG TREND BARS -- body at least bodyFraction of the bar's own range and
// BOTH tails no more than tailFraction of it -- holds until the opposite
// flip, and is UNDEFINED (aiDir = 0) until the first flip ever. The merged
// rule asks for the FIRST leg's start and height in price, which the corpus
// leg counter cannot give (it counts leg numbers, not prices); the flip bar
// supplies both, and it needs no pivot search.
//
// legHigh and legLow are the leg's running extremes, both seeded on the flip
// bar, so the leg's height grows as the leg extends and the retracement level
// travels up with it. The retracement is tested BEFORE this bar's extreme is
// folded in, so a bar that makes a new high and later closes far down clears
// the latch and cannot fire -- a big reversal bar is not "no pullback".
//
// EARLY IN A LEG the height is one bar's range and almost any close clears
// the latch. That is honest to the claim rather than a defect;
// minRetraceFraction is the knob and the merged default of 0.2 is a shallow
// one.
//
// Compared, never divided.
//
// Mirrored: the long side is a new high in a bull leg with no close back down
// through the level, the short side a new low in a bear leg with no close
// back up through it.
//
// Deepest bar touched: consecutiveBars - 1.
allBull = true;
allBear = true;
for (kk = 0; kk < (int)consecutiveBars; ++kk) {
    rng = high[kk] - low[kk];
    if (el_le(close[kk], open[kk])) allBull = false;
    if (el_lt(close[kk] - open[kk], bodyFraction * rng)) allBull = false;
    if (el_gt(high[kk] - close[kk], tailFraction * rng)) allBull = false;
    if (el_gt(open[kk] - low[kk], tailFraction * rng)) allBull = false;
    if (el_ge(close[kk], open[kk])) allBear = false;
    if (el_lt(open[kk] - close[kk], bodyFraction * rng)) allBear = false;
    if (el_gt(close[kk] - low[kk], tailFraction * rng)) allBear = false;
    if (el_gt(high[kk] - open[kk], tailFraction * rng)) allBear = false;
}
flipped = false;
if (allBull && aiDir != 1) {
    aiDir = 1;
    flipped = true;
}
if (allBear && aiDir != -1 && flipped == false) {
    aiDir = -1;
    flipped = true;
}
if (flipped) {
    legHigh = high[0];
    legLow = low[0];
    noPbUp = true;
    noPbDn = true;
}
newHigh = false;
newLow = false;
if (flipped == false) {
    if (el_le(close[0], legHigh - minRetraceFraction * (legHigh - legLow))) noPbUp = false;
    if (el_ge(close[0], legLow + minRetraceFraction * (legHigh - legLow))) noPbDn = false;
    if (el_gt(high[0], legHigh)) {
        newHigh = true;
        legHigh = high[0];
    }
    if (el_lt(low[0], legLow)) {
        newLow = true;
        legLow = low[0];
    }
}
cleanUp = (aiDir == 1) && newHigh && noPbUp;
cleanDn = (aiDir == -1) && newLow && noPbDn;
